import React, { useState } from 'react';
import {
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Typography,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    Divider,
    Button,
    IconButton,
    Switch,
    Checkbox,
    FormGroup,
    FormControlLabel
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import MedicalServicesIcon from '@mui/icons-material/MedicalServices';
import FavoriteIcon from '@mui/icons-material/Favorite';
import { IDisease, IMedicine, useNurseForm } from '../../Context/NurseFormContext';
import { CheckBox, Delete, MedicationOutlined, Payment } from '@mui/icons-material';
import DeleteIcon from '@mui/icons-material/Delete';
import Swal from 'sweetalert2';
import MedicineFormModal from './MedicineFormModal';

const DiseaseAccordionMUI = () => {
    const { diseaseList, setDiseaseList } = useNurseForm();
    const [openMedicine, setOpenMedicine] = useState(false);
    const [diseaseSelected, setDiseaseSelected] = useState<IDisease>()

    const onCloseMedicine = () => setOpenMedicine(false);
    const onOpenMedicine = () => setOpenMedicine(true);

    const handleDelete = (item: IDisease) => {
        Swal.fire({
            title: `คุณต้องการลบกลุ่มโรค "${item.disease_group_name}" ใช่หรือไม่?`,
            showCancelButton: true,
            confirmButtonText: "Confirm",
        }).then(async (result) => {
            if (result.isConfirmed) {
                await onDeleteDisease(item);
            }
        });
    };

    const onDeleteDisease = async (data: IDisease) => {
        var newData = diseaseList;
        newData = newData.filter((item) => item.disease_group != data.disease_group);
        setDiseaseList(newData);
        Swal.fire('ลบสำเร็จ!', '', 'success')
    }

    const onSetDiseaseSelected = (value: IDisease) => setDiseaseSelected(value);
    // <!-- onSumibt Medicine -->
    const onSubmitMedicine = async (data: IMedicine) => {
        var newdata = diseaseList.map(item => {
            if (item.disease_group == diseaseSelected?.disease_group) {
                var newMedicine = item.medicine ?? []
                newMedicine?.push(data)
                return { ...item, medicine: newMedicine }
            } else {
                return item
            }
        })
        setDiseaseList(newdata);
    }
    const onDeleteMedicine = async (data: IMedicine) => {
        var newdata = diseaseList.map(item => {
            if (item.disease_group == diseaseSelected?.disease_group) {
                var newMedicine = item.medicine?.filter(item => item.id != data.id)
                return { ...item, medicine: newMedicine }
            } else {
                return item
            }
        })
        setDiseaseList(newdata);
    }


    return (
        <div style={{ maxWidth: '700px', margin: '20px auto' }}>
            <MedicineFormModal open={openMedicine} onOpen={onOpenMedicine} onClose={onCloseMedicine} onSubmit={onSubmitMedicine} />
            {diseaseList.map((group) => (
                <Accordion key={group.disease_group} style={{ width: '100%' }}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Typography variant="h6" color="primary">
                            {group.disease_group_name}
                        </Typography>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Typography variant="subtitle1" gutterBottom>
                            🩺 อาการ
                        </Typography>
                        <List dense>
                            {group?.symptom?.map((s) => (
                                <ListItem key={s.id}>
                                    <ListItemIcon>
                                        <MedicalServicesIcon color="action" />
                                    </ListItemIcon>
                                    <ListItemText primary={s.name} />
                                </ListItem>
                            ))}
                        </List>
                        <List dense>
                            <ListItem key={group.symptom_other}>
                                <ListItemIcon>
                                    <MedicalServicesIcon color="action" />
                                </ListItemIcon>
                                <ListItemText primary={`อาการอื่นๆ : ${group.symptom_other ?? '-'}`} />
                            </ListItem>
                        </List>
                        <Divider style={{ margin: '10px 0' }} />

                        <Typography variant="subtitle1" gutterBottom>
                            💊 ยา
                        </Typography>
                        <List dense>
                            {group?.medicine?.map((s) => (
                                <ListItem
                                    key={`med-${s.id}`}
                                    secondaryAction={
                                        <IconButton edge="end" onClick={() => { onDeleteMedicine(s) }}>
                                            <DeleteIcon color="error" />
                                        </IconButton>
                                    }
                                >
                                    <ListItemIcon>
                                        <MedicationOutlined color="error" />
                                    </ListItemIcon>
                                    <ListItemText primary={<>{s.name} <br></br> จำนวน : {s.quantity}/{s.unit} <br></br> รวมราคา : {s.total}`</>} />
                                </ListItem>
                            ))}
                        </List>


                        <div style={{ marginTop: 12, display: 'flex', gap: 4, width: '100%' }}>
                            <Button
                                fullWidth
                                variant="outlined"
                                color="success"
                                startIcon={<Payment />}
                                onClick={() => {
                                    onOpenMedicine()
                                    onSetDiseaseSelected(group)
                                }
                                }
                            >
                                จ่ายยา
                            </Button>
                            <Button
                                fullWidth
                                variant="outlined"
                                color="error"
                                startIcon={<Delete />}
                                onClick={() => handleDelete(group)}
                            >
                                ลบ
                            </Button>
                        </div>
                    </AccordionDetails>
                </Accordion>
            ))}
        </div>
    );
};

export default DiseaseAccordionMUI;
